local UIFishPoolChooseFishingCouponPopupNode = Class('UIFishPoolChooseFishingCouponPopupNode')

function UIFishPoolChooseFishingCouponPopupNode:__init()
    self._goodsId = 0
    self._cb = nil
end

function UIFishPoolChooseFishingCouponPopupNode:__delete()
    self._goodsId = 0
    self._cb = nil
end

function UIFishPoolChooseFishingCouponPopupNode:Awake()
    SetButtonAction(self.FontStyleButton, Bind(self, self.OnBtnSelect))
end

---Refresh
function UIFishPoolChooseFishingCouponPopupNode:Refresh(goodsId, cb, isFirst)
    if checkNumber(goodsId) <= 0 then
        return
    end

    self._goodsId = checkNumber(goodsId)
    self._cb = cb

    self:FillSelf()

    CfUtils.SetActive(self.ImgNew, checkNumber(isFirst) == 1)
end

function UIFishPoolChooseFishingCouponPopupNode:FillSelf()
    local vo = GoodsConfMgr:GetInstance():GetGoodsVoById(self._goodsId)
    if not vo then
        return
    end

    CfUtils.FillImage(self.ImgIcon, GoodsConfMgr:GetInstance():GetPhotoPathById(self._goodsId))
    CfUtils.FillText(self.TxtName, vo.name)
    CfUtils.FillText(self.TxtNumber, "x"..GoodsUtils.GetThingNo(self._goodsId))
    --CfUtils.FillText(self.TxtUse, vo.desc)

    SetButtonAction(self.BtnIcon, function()
        GameUtils.ShowCommonTipsBoard(self.BtnIcon, vo.name, nil, vo.quality, self._goodsId)
    end)
end

function UIFishPoolChooseFishingCouponPopupNode:OnBtnSelect()
    if not self._cb then
        return
    end
    self._cb()
end

function UIFishPoolChooseFishingCouponPopupNode:OnDestroy()
    self.controller = nil--luabehaviour 中CSharp对象
    self:Delete()
    self = nil
end

return UIFishPoolChooseFishingCouponPopupNode
